function calculate(a, b, op) {
  if (typeof a !== 'number') return 'invalid a';
  if (typeof b !== 'number') return 'invalid b';
  if (op === '+') return a + b;
  if (op === '-') return a - b;
  if (op === '*') return a * b;
  return 'unknown operator';
}
console.log(calculate(10, 5, '*'));
